patch:
diff --git a/repro/check-ecma-versions.js b/repro/check-ecma-versions.js
new file mode 100644
index 0000000..856a5b5
--- /dev/null
+++ b/repro/check-ecma-versions.js
@@ -0,0 +1,12 @@
+"use strict";
+const { Linter } = require("../lib/api");
+const espree = require("espree");
+const code = "'use strict';\nvar a = 1;\n";
+for (const ecmaVersion of [3, 5, "latest"]) {
+	const msgs = new Linter().verify(code, {
+		languageOptions: { ecmaVersion, sourceType: "script" },
+		rules: { "no-unused-expressions": "error" },
+	});
+	const ast = espree.parse(code, { ecmaVersion: ecmaVersion === "latest" ? "latest" : ecmaVersion });
+	console.log(`ecmaVersion ${ecmaVersion}: body[0].directive=${JSON.stringify(ast.body[0].directive)} -> ${msgs.map(m => `${m.line}:${m.column} ${m.ruleId}: ${m.message}`).join("; ") || "no errors"}`);
+}
diff --git a/repro/eslint.config.js b/repro/eslint.config.js
new file mode 100644
index 0000000..31480f0
--- /dev/null
+++ b/repro/eslint.config.js
@@ -0,0 +1,9 @@
+"use strict";
+// Mirrors the relevant core-js block: packages/core-js/** linted with ecmaVersion: 3
+module.exports = [
+	{
+		files: ["**/*.js"],
+		languageOptions: { ecmaVersion: 3, sourceType: "script" },
+		rules: { "no-unused-expressions": "error" },
+	},
+];
diff --git a/repro/use-strict.js b/repro/use-strict.js
new file mode 100644
index 0000000..96873bb
--- /dev/null
+++ b/repro/use-strict.js
@@ -0,0 +1,2 @@
+'use strict';
+var a = 1;
